{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Arctigenin, a lignan with methoxyphenol and lactone motifs shared with the query aglycone, was detected in rat brain after systemic administration, demonstrating that this lignan scaffold can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Hesperidin, a glycoside bearing a rhamnose-containing disaccharide, crossed the BBB and distributed into mouse brain after oral administration; the query is also a glycoside with a methylated/deoxy sugar, supporting transferable CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Picroside-II, a methoxyphenyl glycoside, rapidly penetrated the BBB and was detected in rat brain, providing additional evidence that glycosylated natural products of this polarity can still achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a much larger triglycoside, hardly passed the BBB; however, its higher sugar count and greater polarity make it less transferable to the query's single bicyclic sugar.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite the query's glycosidic polarity, the preponderance of transferable evidence—especially from permeable lignans and glycosides with similar sugar/methoxyphenol features—supports meaningful CNS access; the single negative triglycoside is outweighed by structural differences.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the query molecule itself.",
    "All evidence analogues have low Morgan similarity to the query.",
    "Uncertainty about whether the glycoside is hydrolyzed to a more permeable aglycone or transported intact across the BBB.",
    "Lack of human or higher-species data for the query chemotype."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

